  axes[2,col].plot(loads['t'],loads['legal_seat_normal_bw'][:,case],label='Actual legal seat normal load (evaluation only)',color='#517b86');axes[2,col].axhline(.05,ls='--',color='#ab654a',label='Unchanged resting requirement')
  axes[0,col].set_title(f"{row['height_cm']:g} cm / +{row['slope_deg']:g}°; row {case}")
