 axes[0,0].set_ylabel('Pitch error (degrees)');axes[1,0].set_ylabel('Pelvis gap (mm)');axes[2,0].set_ylabel('Normal load / BW');fig.tight_layout();fig.savefig(O/'settling_and_load.png',dpi=160);plt.close(fig)
 eventrows=[]
 for r in d['rows']:
  for e in r['geometry_before_events']:eventrows.append([r['case'],e['event'],num(e['time_s']),num(e['saved_sample_s']),e['geometry_available'],num(e['geometry_age_s']),num(e['height_error_mm']),num(e['slope_error_deg'])])
 selected=[[r['case'],f"{r['height_cm']:g} / +{r['slope_deg']:g}",num(r['settle_release_s']),r['max_consecutive_quiet_ticks'],r['final_released'],num(r['max_requested_seat_bw']),r['slip_ticks'],num(r['peak_pelvis_speed_during_slips']),num(r['peak_floor_speed_during_slips']),num(r['final_hold_s'])] for r in d['rows'] if r['selected']]
 outcomes=[[r['case'],f"{r['height_cm']:g} / +{r['slope_deg']:g}",r['stable'],r['slip_ticks'],r['illegal_ticks'],', '.join(k for k,b in r['physical_flags'].items() if b) or 'none',r['warning_ticks']] for r in d['rows']]
 efforts=[]
